  "claims": [
    {
      "claim": "Aryloxypropanolamine analogs metoprolol, propranolol, and pamatolol show oral bioavailability of 54 to 150 percent, all above the 20 percent threshold.",
      "card_ids": ["C01", "C04", "C05", "C07", "C09", "C11", "C12", "C21", "C22", "C23", "C25"]
    },
    {
      "claim": "The methoxyphenyl piperazine analog urapidil shows 72 to 78 percent oral bioavailability in humans, including absolute bioavailability of 72 percent versus intravenous.",
      "card_ids": ["C02", "C06", "C13", "C20", "C27"]
    },
    {
      "claim": "L3 exposure records show measurable oral AUC and Cmax for related compounds: ICI 141,292 (aryloxypropanolamine amide) AUC 24.6 to 30.9 µg·ml−1·hr and Cmax 5.4 µg/mL in dogs, propranolol Cmax 50.5 ng/mL in humans, levodropropizine AUC about 1000 h·ng/mL, and recainam (2,6-dimethylphenyl amide) Cmax 2.3 µg/mL with AUC 13.3 µg·h/mL after 400 mg.",
      "card_ids": ["C48", "C50", "C51", "C52", "C53", "C54", "C55"]
    },
    {
      "claim": "No L3 record provides affirmative evidence of F below 20 percent; C47 and C56 are interaction studies, and C57 dasatinib exposure lacks an intravenous comparator and has low structural transfer.",
      "card_ids": ["C46", "C47", "C49", "C56", "C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C48", "C50", "C51", "C52", "C53", "C54", "C55"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C46", "C47", "C49", "C56", "C57"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "L3 exposure records lack intravenous comparators, so they cannot quantify absolute bioavailability.",
    "The piperazine acetamide 2,6-dimethylanilide tail is not present in any reference compound.",
    "No query-specific data on first-pass metabolism, amidase hydrolysis, efflux transport, or formulation effects.",
    "Several reference values were obtained under cirrhosis, fed, or modified-release conditions that may not match the query condition."
  ],
  "decision_summary": "L3 oral exposure records for structurally related aryloxypropanolamine and piperazine compounds show measurable oral AUC and Cmax, consistent with the high oral bioavailability of the L1 and L2 analogs; no L3 record supports F below 20 percent. Prediction high, confidence high, revision strengthen."
}

